function Alerts({ alerts }) {

    return (

        <div style={{
            marginTop: '30px'
        }}>

            <h2>System Alerts</h2>

            {alerts.map((alert, index) => (

                <div
                    key={index}
                   style={{
    background: '#fff4f4',
    color: '#b91c1c',
    padding: '18px',
    borderRadius: '14px',
    marginBottom: '12px',
    borderLeft: '6px solid #ef4444',
    boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
}}
                >
                    {alert}
                </div>

            ))}

        </div>

    );

}

export default Alerts;
